import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Core 与参考业务的边界","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/boundaries.md","filePath":"architecture/boundaries.md"}'),o={name:"architecture/boundaries.md"};function n(i,e,l,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="core-与参考业务的边界" tabindex="-1">Core 与参考业务的边界 <a class="header-anchor" href="#core-与参考业务的边界" aria-label="Permalink to &quot;Core 与参考业务的边界&quot;">​</a></h1><p>当前 T01 只有通用服务状态这一条完整请求。它属于 Core，不属于知识库示例。</p><ul><li><strong>platform</strong> 拥有配置、连接池、迁移运行与日志初始化，不依赖应用或知识库类型。</li><li><strong>app</strong> 拥有公开 HTTP 合同、Core 模块和必要的用例。</li><li><strong>API 入口</strong> 组装 Router；未来在这里挂载可替换的知识库模块。</li><li><strong>contracts / sdk</strong> 来自 OpenAPI 生成；SDK 的类型使用 contracts。</li><li><strong>core</strong> 放平台无关的客户端 helper。</li><li><strong>ui / views</strong> 分别提供通用 React DOM 组件与可共享页面。</li><li><strong>Web 入口</strong> 拥有浏览器和 Router 接线，shared View 不自行访问 window。</li></ul><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d3d0275ea6709e18f371a558d5bfa742a4903672/examples/knowledge-base/manifest.json" target="_blank" rel="noreferrer">示例所有权清单</a>目前明确标记知识库尚未实现，ownedPaths 为空，列出未来组装位置。不能为了准备目录而宣称已经有注册或文档业务。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>当前检查验证包依赖方向、平台无关代码的导入以及组装清单。它不声称已经验证不存在的业务表隔离或完整删例能力；实际移除工具属于对应实施票。</p><p>引入自己的业务时，使用公开身份、文件和任务能力；不要让 Core 通过私有表或反向 import 依赖示例。进一步决策见<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d3d0275ea6709e18f371a558d5bfa742a4903672/docs/adr/0002-executable-removable-reference.md" target="_blank" rel="noreferrer">可移除教程 ADR</a>。</p><hr><p>源码版本：<code>d3d0275ea670</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/d3d0275ea6709e18f371a558d5bfa742a4903672/docs/architecture/module-boundaries.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>',9)])])}const b=a(o,[["render",n]]);export{u as __pageData,b as default};
